template<class ContainerAllocator>
struct Printer< ::microstrain_inertial_msgs::HumanReadableStatus_<ContainerAllocator> >
{
  template<typename Stream> static void stream(Stream& s, const std::string& indent, const ::microstrain_inertial_msgs::HumanReadableStatus_<ContainerAllocator>& v)
  {
    s << indent << "header: ";
    s << std::endl;
    Printer< ::std_msgs::Header_<ContainerAllocator> >::stream(s, indent + "  ", v.header);
    s << indent << "device_info: ";
    s << std::endl;
    Printer< ::microstrain_inertial_msgs::MipBaseDeviceInfo_<ContainerAllocator> >::stream(s, indent + "  ", v.device_info);
    s << indent << "gnss_state: ";
    Printer<std::basic_string<char, std::char_traits<char>, typename std::allocator_traits<ContainerAllocator>::template rebind_alloc<char>>>::stream(s, indent + "  ", v.gnss_state);
    s << indent << "dual_antenna_fix_type: ";
    Printer<std::basic_string<char, std::char_traits<char>, typename std::allocator_traits<ContainerAllocator>::template rebind_alloc<char>>>::stream(s, indent + "  ", v.dual_antenna_fix_type);
    s << indent << "filter_state: ";
    Printer<std::basic_string<char, std::char_traits<char>, typename std::allocator_traits<ContainerAllocator>::template rebind_alloc<char>>>::stream(s, indent + "  ", v.filter_state);
    s << indent << "status_flags[]" << std::endl;
    for (size_t i = 0; i < v.status_flags.size(); ++i)
    {
      s << indent << "  status_flags[" << i << "]: ";
      Printer<std::basic_string<char, std::char_traits<char>, typename std::allocator_traits<ContainerAllocator>::template rebind_alloc<char>>>::stream(s, indent + "  ", v.status_flags[i]);
    }
    s << indent << "continuous_bit_flags[]" << std::endl;
    for (size_t i = 0; i < v.continuous_bit_flags.size(); ++i)
    {
      s << indent << "  continuous_bit_flags[" << i << "]: ";
      Printer<std::basic_string<char, std::char_traits<char>, typename std::allocator_traits<ContainerAllocator>::template rebind_alloc<char>>>::stream(s, indent + "  ", v.continuous_bit_flags[i]);
    }
  }
};

